<?php
declare(strict_types=1);

require_once __DIR__.'/../lib/safety_vote_company_visibility_remediation.php';

function sv_cvr_actor(array$user):string{return trim((string)($user['id']??$user['EmployeeID']??''));}
function sv_cvr_role(array$user):string{return strtoupper(trim((string)($user['role']??$user['Role']??'')));}
function sv_cvr_enabled(PDO$pdo,bool$lock=false):bool{$sql="SELECT SettingKey,SettingValue FROM SafetyVote_Settings WHERE SettingKey IN ('company_visibility_remediation_contract','company_visibility_remediation_enabled')".($lock?' FOR UPDATE':'');$stmt=$pdo->query($sql);$map=[];foreach($stmt->fetchAll()as$row)$map[$row['SettingKey']]=(string)$row['SettingValue'];return($map['company_visibility_remediation_enabled']??'0')==='1'&&($map['company_visibility_remediation_contract']??'')===SV_COMPANY_VISIBILITY_REMEDIATION_CONTRACT;}
function sv_cvr_rows(PDO$pdo,bool$lock=false):array{$stmt=$pdo->query("SELECT c.id,c.CampaignCode,c.Status,c.DiscoveryMode,c.RowVersion,c.IsHidden,c.IsTest,v.TitleTh FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID ORDER BY c.id".($lock?' FOR UPDATE':''));return$stmt->fetchAll()?:[];}
function sv_cvr_audit(PDO$pdo,array$user,string$action,string$type,$target,string$detail,array$metadata,$campaignId=null):void{$stmt=$pdo->prepare('INSERT INTO SafetyVote_AuditLogs(CampaignID,ActorEmployeeID,ActorRole,Action,TargetType,TargetID,BoundedDetail,MetadataJson) VALUES(?,?,?,?,?,?,?,?)');$stmt->execute([$campaignId,sv_cvr_actor($user),sv_cvr_role($user),$action,$type,(string)$target,mb_substr($detail,0,1000),json_encode($metadata,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);}

function handle_safety_vote_company_visibility_remediation_routes(string$method,string$path):bool{
    $preview=$path==='/safety-vote/admin/company-visibility-remediation/preview';
    $apply=$path==='/safety-vote/admin/company-visibility-remediation/apply';
    $rollback=route_params($path,'/safety-vote/admin/company-visibility-remediation/:batchId/rollback');
    if(!$preview&&!$apply&&$rollback===null)return false;
    $user=require_user();sv_require_schema();sv_require_permission($user,'SAFETY_VOTE_MANAGE');$pdo=db();
    if($preview&&$method==='GET'){if(!sv_cvr_enabled($pdo))json_response(['success'=>false,'code'=>'REMEDIATION_DISABLED','message'=>'Company visibility remediation is disabled.'],503);json_response(['success'=>true,'data'=>sv_cvr_plan(sv_cvr_rows($pdo))]);}
    if($apply&&$method==='POST'){
        $body=json_body();$reason=mb_substr(trim((string)($body['reason']??'')),0,1000);$previewHash=strtolower(trim((string)($body['previewHash']??'')));$confirmation=trim((string)($body['confirmation']??''));$key=trim((string)($_SERVER['HTTP_IDEMPOTENCY_KEY']??''));
        if(mb_strlen($reason)<10||!preg_match('/^[a-f0-9]{64}$/',$previewHash)||strlen($key)<16)json_response(['success'=>false,'code'=>'VALIDATION_FAILED','message'=>'Reason, preview hash and Idempotency-Key are required.'],400);
        $idempotencyHash=hash('sha256',sv_cvr_actor($user)."\n".$key);$pdo->beginTransaction();
        try{
            if(!sv_cvr_enabled($pdo,true)){$pdo->rollBack();json_response(['success'=>false,'code'=>'REMEDIATION_DISABLED'],503);}
            $stmt=$pdo->prepare('SELECT * FROM SafetyVote_VisibilityRemediationBatches WHERE IdempotencyHash=? FOR UPDATE');$stmt->execute([$idempotencyHash]);$replay=$stmt->fetch();if($replay){$pdo->commit();json_response(['success'=>true,'data'=>['batchId'=>(int)$replay['id'],'status'=>$replay['Status'],'replayed'=>true,'previewHash'=>$replay['PreviewHash'],'candidateCount'=>(int)$replay['CandidateCount']]]);}
            $plan=sv_cvr_plan(sv_cvr_rows($pdo,true));if($plan['previewHash']!==$previewHash){$pdo->rollBack();json_response(['success'=>false,'code'=>'REMEDIATION_PREVIEW_STALE','details'=>['currentPreviewHash'=>$plan['previewHash']]],409);}if($confirmation!==$plan['exactConfirmation']){$pdo->rollBack();json_response(['success'=>false,'code'=>'REMEDIATION_CONFIRMATION_REQUIRED','details'=>['exactConfirmation'=>$plan['exactConfirmation']]],400);}
            $stmt=$pdo->prepare("INSERT INTO SafetyVote_VisibilityRemediationBatches(ContractVersion,PreviewHash,CandidateCount,Reason,IdempotencyHash,Status,AppliedBy) VALUES(?,?,?,?,?,'Applied',?)");$stmt->execute([SV_COMPANY_VISIBILITY_REMEDIATION_CONTRACT,$plan['previewHash'],$plan['counts']['remediate'],$reason,$idempotencyHash,sv_cvr_actor($user)]);$batchId=(int)$pdo->lastInsertId();
            $update=$pdo->prepare("UPDATE SafetyVote_Campaigns SET DiscoveryMode='public_listing',UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=? AND DiscoveryMode='eligible_only' AND RowVersion=?");$insert=$pdo->prepare("INSERT INTO SafetyVote_VisibilityRemediationItems(BatchID,CampaignID,CampaignCode,OriginalDiscoveryMode,TargetDiscoveryMode,BeforeRowVersion,AppliedRowVersion,Status) VALUES(?,?,?,?,?,?,?,'Applied')");
            foreach($plan['items']as$item)if($item['decision']==='remediate'){$update->execute([sv_cvr_actor($user),$item['id'],$item['rowVersion']]);if($update->rowCount()!==1)throw new RuntimeException('REMEDIATION_CONFLICT');$insert->execute([$batchId,$item['id'],$item['campaignCode'],$item['discoveryMode'],$item['targetDiscoveryMode'],$item['rowVersion'],$item['rowVersion']+1]);sv_cvr_audit($pdo,$user,'SAFETY_VOTE_COMPANY_VISIBILITY_REMEDIATED','SafetyVote_Campaign',$item['id'],'eligible_only -> public_listing; batch='.$batchId,['batchId'=>$batchId,'previewHash'=>$plan['previewHash'],'eligibilityChanged'=>false,'resultEvidenceChanged'=>false],$item['id']);}
            sv_cvr_audit($pdo,$user,'SAFETY_VOTE_COMPANY_VISIBILITY_REMEDIATION_APPLIED','SafetyVote_VisibilityRemediationBatch',$batchId,'campaigns='.$plan['counts']['remediate'],['previewHash'=>$plan['previewHash'],'protectedEvidence'=>$plan['protectedEvidence']]);$pdo->commit();json_response(['success'=>true,'data'=>['batchId'=>$batchId,'status'=>'Applied','replayed'=>false,'previewHash'=>$plan['previewHash'],'candidateCount'=>$plan['counts']['remediate'],'protectedEvidence'=>$plan['protectedEvidence']]],201);
        }catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();$conflict=$error->getMessage()==='REMEDIATION_CONFLICT';json_response(['success'=>false,'code'=>$conflict?'REMEDIATION_CONFLICT':'REMEDIATION_APPLY_FAILED'], $conflict?409:500);}
    }
    if($rollback!==null&&$method==='POST'){
        $batchId=(int)$rollback['batchId'];$body=json_body();$reason=mb_substr(trim((string)($body['reason']??'')),0,1000);$confirmation=trim((string)($body['confirmation']??''));if($batchId<1||mb_strlen($reason)<10||$confirmation!=='ROLLBACK COMPANY VISIBILITY '.$batchId)json_response(['success'=>false,'code'=>'ROLLBACK_CONFIRMATION_REQUIRED'],400);$pdo->beginTransaction();
        try{if(!sv_cvr_enabled($pdo,true)){$pdo->rollBack();json_response(['success'=>false,'code'=>'REMEDIATION_DISABLED'],503);}$stmt=$pdo->prepare('SELECT * FROM SafetyVote_VisibilityRemediationBatches WHERE id=? FOR UPDATE');$stmt->execute([$batchId]);$batch=$stmt->fetch();if(!$batch){$pdo->rollBack();json_response(['success'=>false,'code'=>'REMEDIATION_BATCH_NOT_FOUND'],404);}if($batch['Status']==='RolledBack'){$pdo->commit();json_response(['success'=>true,'data'=>['batchId'=>$batchId,'status'=>'RolledBack','replayed'=>true]]);}$stmt=$pdo->prepare("SELECT i.*,c.DiscoveryMode,c.RowVersion FROM SafetyVote_VisibilityRemediationItems i JOIN SafetyVote_Campaigns c ON c.id=i.CampaignID WHERE i.BatchID=? AND i.Status='Applied' ORDER BY i.id FOR UPDATE");$stmt->execute([$batchId]);$items=$stmt->fetchAll();$conflicts=[];foreach($items as$item)if($item['DiscoveryMode']!==$item['TargetDiscoveryMode']||(int)$item['RowVersion']!==(int)$item['AppliedRowVersion'])$conflicts[]=(int)$item['CampaignID'];if($conflicts){$pdo->rollBack();json_response(['success'=>false,'code'=>'REMEDIATION_ROLLBACK_CONFLICT','details'=>['campaignIds'=>$conflicts]],409);}foreach($items as$item){$pdo->prepare('UPDATE SafetyVote_Campaigns SET DiscoveryMode=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?')->execute([$item['OriginalDiscoveryMode'],sv_cvr_actor($user),$item['CampaignID']]);$pdo->prepare("UPDATE SafetyVote_VisibilityRemediationItems SET Status='RolledBack' WHERE id=?")->execute([$item['id']]);sv_cvr_audit($pdo,$user,'SAFETY_VOTE_COMPANY_VISIBILITY_REMEDIATION_ROLLED_BACK','SafetyVote_Campaign',$item['CampaignID'],'batch='.$batchId.'; restored='.$item['OriginalDiscoveryMode'],['batchId'=>$batchId,'eligibilityChanged'=>false,'resultEvidenceChanged'=>false],$item['CampaignID']);}$pdo->prepare("UPDATE SafetyVote_VisibilityRemediationBatches SET Status='RolledBack',RolledBackBy=?,RolledBackAt=NOW(),RollbackReason=? WHERE id=?")->execute([sv_cvr_actor($user),$reason,$batchId]);$pdo->commit();json_response(['success'=>true,'data'=>['batchId'=>$batchId,'status'=>'RolledBack','replayed'=>false,'restoredCount'=>count($items)]]);
        }catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();json_response(['success'=>false,'code'=>'REMEDIATION_ROLLBACK_FAILED'],500);}
    }
    json_response(['success'=>false,'code'=>'METHOD_NOT_ALLOWED'],405);return true;
}
